1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: readonly Damage[];
19	};
20	
21	export type QuoteStep = {
22	  op: "quote";
23	  items: readonly Item[];
24	};
25	
26	export type ClaimStep = {
27	  op: "claim";
28	  // Zero-based index of the quote step that created the policy.
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: readonly Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	// One entry per scenario step, in order. Each step's `op` selects the shape.
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export type ScenarioResult = {
47	  results: StepResult[];
48	};
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	// Every percentage modifier is a delta computed against an *unmodified* base
64	// and summed with the others — modifiers never compound. Policy-wide ones use
65	// the policy base, item-specific ones the affected item's own base premium.
66	//
67	// Percentages stay in integer percent points: multiply first, divide by 100
68	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
69	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
70	const percentOf = (amount: number, percent: number): number =>
71	  (amount * percent) / 100;
72	
73	// The MHPCO insures only the items on its price list. Anything else is a
74	// rejected policy, not a zero-priced one — so an absent type throws rather
75	// than defaulting to zero, and every caller may treat the result as a price.
76	const insurableValueOf = (
77	  table: Record<string, number>,
78	  type: string,
79	): number => {
80	  const value = table[type];
81	
82	  if (value === undefined) {
83	    throw new Error(`unknown item type: ${type}`);
84	  }
85	
86	  return value;
87	};
88	
89	// Rejecting uninsurable items is a rule of its own, so it is stated once and
90	// up front rather than left to fall out of whichever pricing step happens to
91	// look a type up first. Without this, a block of three unknown items would
92	// price through `basePremiumOfTypeGroup` untouched and only fail later, by
93	// luck, in the per-item surcharge pass.
94	const rejectUninsurableItems = (items: readonly Item[]): void => {
95	  for (const item of items) {
96	    insurableValueOf(BASE_PREMIUMS, item.type);
97	  }
98	};
99	
100	const BLOCK_SIZE = 3;
101	const BLOCK_BASE_PREMIUM = 60;
102	
103	// How many of each key a collection holds. Items and damages both need this,
104	// over different fields — `keyOf` is the only thing that differs, so it is the
105	// only thing the caller supplies.
106	const tally = <Element>(
107	  elements: readonly Element[],
108	  keyOf: (element: Element) => string,
109	): Map<string, number> => {
110	  const counts = new Map<string, number>();
111	
112	  for (const element of elements) {
113	    const key = keyOf(element);
114	    counts.set(key, (counts.get(key) ?? 0) + 1);
115	  }
116	
117	  return counts;
118	};
119	
120	const countByType = (items: readonly Item[]): Map<string, number> =>
121	  tally(items, (item) => item.type);
122	
123	// Prices one type-group. A block of exactly three costs a flat rate instead of
124	// three individual premiums — deliberately including main items, not just the
125	// small components. Callers have already rejected uninsurable types, so the
126	// flat-rate branch skipping the price list is safe rather than a hole.
127	const basePremiumOfTypeGroup = (type: string, count: number): number =>
128	  count === BLOCK_SIZE
129	    ? BLOCK_BASE_PREMIUM
130	    : count * insurableValueOf(BASE_PREMIUMS, type);
131	
132	const policyBaseOf = (items: readonly Item[]): number =>
133	  [...countByType(items)].reduce(
134	    (total, [type, count]) => total + basePremiumOfTypeGroup(type, count),
135	    0,
136	  );
137	
138	// A modifier rule: when `applies` holds for the subject, `percent` percent of
139	// the relevant base premium is added. A negative percent is a discount. Every
140	// rule whose predicate holds contributes; the deltas are summed, never
141	// compounded.
142	type ModifierRule<Subject> = {
143	  applies: (subject: Subject) => boolean;
144	  percent: number;
145	};
146	
147	const sumApplicablePercents = <Subject>(
148	  rules: ModifierRule<Subject>[],
149	  subject: Subject,
150	): number =>
151	  rules.reduce(
152	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
153	    0,
154	  );
155	
156	// Policy-wide modifiers: each is a percentage of the policy base premium.
157	//
158	// Their subject is the circumstances under which the quote is issued — not the
159	// customer alone, and not the issued policy either (that is `IssuedPolicy`,
160	// which a claim reads). Today those circumstances are just who is asking and
161	// how many quotes they have had; rules that depend on more read the field they
162	// need off the same subject.
163	type QuoteCircumstances = {
164	  customer: Customer;
165	  // Zero-based ordinal among the customer's quotes in this scenario.
166	  quoteOrdinal: number;
167	};
168	
169	const LOYALTY_YEARS_THRESHOLD = 2;
170	const LOYALTY_DISCOUNT_PERCENT = -20;
171	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
172	
173	const POLICY_MODIFIER_RULES: ModifierRule<QuoteCircumstances>[] = [
174	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
175	  {
176	    applies: ({ customer }) =>
177	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
178	    percent: LOYALTY_DISCOUNT_PERCENT,
179	  },
180	  {
181	    applies: ({ quoteOrdinal }) => quoteOrdinal > 0,
182	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
183	  },
184	];
185	
186	const policyModifierDelta = (
187	  policyBase: number,
188	  circumstances: QuoteCircumstances,
189	): number =>
190	  percentOf(
191	    policyBase,
192	    sumApplicablePercents(POLICY_MODIFIER_RULES, circumstances),
193	  );
194	
195	// Item-specific modifiers: each is a percentage of the affected item's own
196	// base premium.
197	const CURSE_SURCHARGE_PERCENT = 50;
198	const HIGH_ENCHANTMENT_THRESHOLD = 5;
199	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
200	
201	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
202	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
203	  {
204	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
205	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
206	  },
207	];
208	
209	const itemModifierDelta = (item: Item): number =>
210	  percentOf(
211	    insurableValueOf(BASE_PREMIUMS, item.type),
212	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
213	  );
214	
215	const quote = (
216	  items: readonly Item[],
217	  circumstances: QuoteCircumstances,
218	): number => {
219	  rejectUninsurableItems(items);
220	
221	  const policyBase = policyBaseOf(items);
222	  const modifiers =
223	    policyModifierDelta(policyBase, circumstances) +
224	    items.reduce((total, item) => total + itemModifierDelta(item), 0);
225	
226	  // Rounding is in the MHPCO's favour: premiums round up.
227	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
228	};
229	
230	// Insurance values are what an item is insured FOR, distinct from the base
231	// premium charged to insure it.
232	const INSURANCE_VALUES: Record<string, number> = {
233	  sword: 1000,
234	  amulet: 600,
235	  staff: 800,
236	  potion: 400,
237	  rune: 250,
238	  moonstone: 250,
239	};
240	
241	const DEDUCTIBLE_PER_DAMAGE = 100;
242	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
243	
244	const insuranceSumOf = (items: readonly Item[]): number =>
245	  items.reduce(
246	    (sum, item) => sum + insurableValueOf(INSURANCE_VALUES, item.type),
247	    0,
248	  );
249	
250	// A policy as a claim sees it: the items it covers, and how much of its cap
251	// is still available. Successive claims against the same policy draw the cap
252	// down, so `remainingCap` is state that outlives the claim step that reads it.
253	type IssuedPolicy = {
254	  items: readonly Item[];
255	  remainingCap: number;
256	};
257	
258	const issuePolicy = (items: readonly Item[]): IssuedPolicy => ({
259	  items,
260	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
261	});
262	
263	// A reimbursement clause: when `applies` holds for the damaged item, the
264	// damage is reimbursed at `percent` of its amount.
265	//
266	// Unlike the premium modifiers above, clauses do NOT sum. When several apply
267	// the most restrictive one wins — the lowest percentage. So a clause table
268	// needs no ordering to be correct, and adding a clause can only ever lower a
269	// payout, never raise it.
270	type ReimbursementClause = {
271	  applies: (item: Item) => boolean;
272	  percent: number;
273	};
274	
275	const FULL_REIMBURSEMENT_PERCENT = 100;
276	const HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
277	const HALVED_REIMBURSEMENT_PERCENT = 50;
278	
279	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
280	  {
281	    applies: (item) =>
282	      (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT,
283	    percent: HALVED_REIMBURSEMENT_PERCENT,
284	  },
285	];
286	
287	// Full reimbursement is the default: with no clause applying, the damage is
288	// covered in full.
289	const reimbursementPercentFor = (item: Item): number =>
290	  REIMBURSEMENT_CLAUSES.reduce(
291	    (percent, clause) =>
292	      clause.applies(item) ? Math.min(percent, clause.percent) : percent,
293	    FULL_REIMBURSEMENT_PERCENT,
294	  );
295	
296	// The damaged item a damage entry refers to, or undefined if the policy does
297	// not cover that type. Matched by type alone, so with two swords insured both
298	// sword damages resolve to the first. That is harmless while every item of a
299	// type is interchangeable for reimbursement purposes; the case that forces a
300	// positional match is rejecting more damage entries of a type than the policy
301	// covers, which needs a count rather than a lookup.
302	const insuredItemFor = (
303	  policy: IssuedPolicy,
304	  damage: Damage,
305	): Item | undefined =>
306	  policy.items.find((item) => item.type === damage.itemType);
307	
308	// A damage entry that has passed validation, paired with the insured item it
309	// was resolved against. Producing this is what the validation pass is *for*:
310	// downstream code takes the item as given rather than re-looking it up and
311	// re-handling a "not covered" case that can no longer occur.
312	type AdmittedDamage = {
313	  damage: Damage;
314	  damagedItem: Item;
315	};
316	
317	// Admits an incident's damages, or refuses the claim outright. Stated here,
318	// once and up front, for the same reason `rejectUninsurableItems` is: a
319	// rejection is a rule in its own right, not something that should fall out of
320	// whichever computation step happens to trip over it first.
321	//
322	// Running before any money is computed also keeps the settlement total — a
323	// function that can throw partway through an accumulation is doing control
324	// flow through the accumulator.
325	//
326	// This is the incident-level pass, so a rule that needs to see all the damages
327	// at once — counting entries per type against what the policy covers — has a
328	// home here, whereas it could never live inside a per-damage function.
329	const admitDamages = (
330	  policy: IssuedPolicy,
331	  incident: Incident,
332	): AdmittedDamage[] => {
333	  // A policy cannot lose more of a thing than it insures.
334	  const insuredCounts = countByType(policy.items);
335	
336	  const damagedCounts = tally(incident.damages, (damage) => damage.itemType);
337	
338	  for (const [itemType, damagedCount] of damagedCounts) {
339	    const insuredCount = insuredCounts.get(itemType) ?? 0;
340	
341	    if (damagedCount > insuredCount) {
342	      throw new Error(
343	        `more ${itemType} damages than the policy covers: ` +
344	          `${damagedCount} of ${insuredCount}`,
345	      );
346	    }
347	  }
348	
349	  return incident.damages.map((damage) => {
350	    // Damage is a loss, never a credit.
351	    if (damage.amount < 0) {
352	      throw new Error(`negative damage amount: ${damage.amount}`);
353	    }
354	
355	    const damagedItem = insuredItemFor(policy, damage);
356	
357	    // A policy only answers for what it covers.
358	    if (damagedItem === undefined) {
359	      throw new Error(`item not covered by the policy: ${damage.itemType}`);
360	    }
361	
362	    return { damage, damagedItem };
363	  });
364	};
365	
366	// What a single admitted damage is reimbursable for: the reimbursement its
367	// clauses allow, less the deductible. The deductible is charged once per
368	// damaged item, not once per incident, so it belongs here rather than at the
369	// incident level. The policy's cap is NOT applied here — it limits the
370	// incident as a whole, so only `settleClaim` can apply it.
371	//
372	// The clauses grade the reimbursement by the *damaged item's* properties
373	// (enchantment, material), which is why the resolved item travels with the
374	// damage instead of the policy being passed in to look it up again.
375	const reimbursableForDamage = ({
376	  damage,
377	  damagedItem,
378	}: AdmittedDamage): number =>
379	  percentOf(damage.amount, reimbursementPercentFor(damagedItem)) -
380	  DEDUCTIBLE_PER_DAMAGE;
381	
382	// Settles one incident against a policy, returning the payout and the policy
383	// as it stands afterwards. The cap is drawn down here — that is what makes a
384	// second claim against the same policy see less headroom than the first.
385	const settleClaim = (
386	  policy: IssuedPolicy,
387	  incident: Incident,
388	): { payout: number; policy: IssuedPolicy } => {
389	  // Admit every damage before paying for any: a claim is refused as a whole,
390	  // so no part of it should be priced until all of it is known to be valid.
391	  const admitted = admitDamages(policy, incident);
392	
393	  const reimbursable = admitted.reduce(
394	    (total, admittedDamage) => total + reimbursableForDamage(admittedDamage),
395	    0,
396	  );
397	
398	  // Rounding is in the MHPCO's favour: payouts round down, mirroring the
399	  // premium's round up.
400	  // The policy pays at most what is left of its cap.
401	  const payout = Math.min(Math.floor(reimbursable), policy.remainingCap);
402	
403	  return {
404	    payout,
405	    policy: { ...policy, remainingCap: policy.remainingCap - payout },
406	  };
407	};
408	
409	// What the scenario has established by the time a step runs. Threaded through
410	// the steps in order: each step reads it, and hands the next step the progress
411	// its own execution made.
412	type ScenarioProgress = {
413	  // How many quotes the customer has already been given. Only quote steps
414	  // advance this, so an op that is not a quote leaves it untouched.
415	  quotesSoFar: number;
416	  // Policies created by earlier quote steps, keyed by their step index — the
417	  // handle a later claim step names in its `policy` field.
418	  policies: Map<number, IssuedPolicy>;
419	};
420	
421	// The policy a claim step names. A claim against an index no quote step
422	// created currently settles against an empty policy: no items, so every damage
423	// is uncovered, and a zero cap. That is a placeholder standing in for a rule
424	// nobody has written yet, not a decision — the honest behaviour is almost
425	// certainly to reject the claim outright, the way an unknown item type is
426	// rejected. Named here so the choice is visible at the point it is made, and
427	// so the test that pins it down has one place to change.
428	const policyClaimedAgainst = (
429	  policies: ReadonlyMap<number, IssuedPolicy>,
430	  policyIndex: number,
431	): IssuedPolicy => policies.get(policyIndex) ?? issuePolicy([]);
432	
433	// Runs one step against the progress so far, returning its result alongside
434	// the progress the *next* step inherits. Dispatch on `step.op` lives here:
435	// a new op is a new branch, and the loop below is unaffected.
436	const runStep = (
437	  step: Step,
438	  stepIndex: number,
439	  customer: Customer,
440	  progress: ScenarioProgress,
441	): { result: StepResult; progress: ScenarioProgress } => {
442	  if (step.op === "claim") {
443	    const settled = settleClaim(
444	      policyClaimedAgainst(progress.policies, step.policy),
445	      step.incident,
446	    );
447	
448	    return {
449	      result: {
450	        payout: settled.payout,
451	        remainingCap: settled.policy.remainingCap,
452	      },
453	      // The drawn-down policy replaces the one the claim was made against, so
454	      // the next claim against it starts from the reduced cap.
455	      progress: {
456	        ...progress,
457	        policies: new Map(progress.policies).set(step.policy, settled.policy),
458	      },
459	    };
460	  }
461	
462	  return {
463	    result: {
464	      premium: quote(step.items, {
465	        customer,
466	        quoteOrdinal: progress.quotesSoFar,
467	      }),
468	    },
469	    progress: {
470	      quotesSoFar: progress.quotesSoFar + 1,
471	      policies: new Map(progress.policies).set(
472	        stepIndex,
473	        issuePolicy(step.items),
474	      ),
475	    },
476	  };
477	};
478	
479	export const runScenario = (scenario: Scenario): ScenarioResult => {
480	  const results: StepResult[] = [];
481	  let progress: ScenarioProgress = { quotesSoFar: 0, policies: new Map() };
482	
483	  for (const [stepIndex, step] of scenario.steps.entries()) {
484	    const stepRun = runStep(step, stepIndex, scenario.customer, progress);
485	
486	    results.push(stepRun.result);
487	    progress = stepRun.progress;
488	  }
489	
490	  return { results };
491	};
